// ---- Tuple struct definition ----
struct Color(i32, i32, i32);
struct Point2D(f32, f32);
struct Vector3D(f32, f32, f32);
struct Health(i32);

// ---- Tuple struct with methods ----
impl Point2D {
    fn new(x: f32, y: f32) -> Point2D {
        Point2D(x, y)
    }

    fn distance_from_origin(&self) -> f32 {
        (self.0 * self.0 + self.1 * self.1).sqrt()
    }

    fn add(&self, other: &Point2D) -> Point2D {
        Point2D(self.0 + other.0, self.1 + other.1)
    }
}

impl Vector3D {
    fn new(x: f32, y: f32, z: f32) -> Vector3D {
        Vector3D(x, y, z)
    }

    fn magnitude(&self) -> f32 {
        (self.0 * self.0 + self.1 * self.1 + self.2 * self.2).sqrt()
    }

    fn scale(&self, factor: f32) -> Vector3D {
        Vector3D(self.0 * factor, self.1 * factor, self.2 * factor)
    }
}

fn main() {
    // ---- Creating tuple structs ----
    let red = Color(255, 0, 0);
    let green = Color(0, 255, 0);
    let blue = Color(0, 0, 255);

    println!("Red: ({}, {}, {})", red.0, red.1, red.2);
    println!("Green: ({}, {}, {})", green.0, green.1, green.2);
    println!("Blue: ({}, {}, {})", blue.0, blue.1, blue.2);

    // ---- Point2D operations ----
    let p1 = Point2D::new(3.0, 4.0);
    let p2 = Point2D::new(1.0, 2.0);

    println!("p1: ({}, {})", p1.0, p1.1);
    println!("p2: ({}, {})", p2.0, p2.1);
    println!("Distance of p1 from origin: {}", p1.distance_from_origin());

    let p3 = p1.add(&p2);
    println!("p1 + p2 = ({}, {})", p3.0, p3.1);

    // ---- Vector3D operations ----
    let v1 = Vector3D::new(1.0, 2.0, 3.0);
    let v2 = v1.scale(2.0);

    println!("v1: ({}, {}, {})", v1.0, v1.1, v1.2);
    println!("v1 magnitude: {}", v1.magnitude());
    println!("v1 * 2 = ({}, {}, {})", v2.0, v2.1, v2.2);

    // ---- Tuple struct with single field (newtype) ----
    let health = Health(100);
    let max_health = Health(120);

    println!("Health: {}/{}", health.0, max_health.0);

    // ---- Destructuring tuple structs ----
    let Color(r, g, b) = red;
    println!("Destructured Red: r={}, g={}, b={}", r, g, b);

    let Point2D(x, y) = p1;
    println!("p1 destructured: x={}, y={}", x, y);
}

// ---- Newtype pattern ----
// Wrapping a single value to add type safety
struct PlayerName(String);
struct PlayerId(u32);
struct Score(i32);

impl PlayerName {
    fn new(name: &str) -> PlayerName {
        PlayerName(name.to_string())
    }

    fn as_str(&self) -> &str {
        &self.0
    }
}

fn main2() {
    let name = PlayerName::new("Hero");
    let id = PlayerId(42);
    let score = Score(1000);

    println!("Name: {}", name.as_str());
    println!("ID: {}", id.0);
    println!("Score: {}", score.0);
}

